const closedPattern=/\b(?:not currently accepting applications|no longer accepting applications|applications (?:are|have been) closed|(?:this )?(?:job|position|vacancy) (?:is|has been) (?:closed|filled|expired)|(?:this )?(?:job|position) is no longer available)\b(?!\s+(?:from|for)\b)/i;
let knownClosed=new Set(),pending=null,lastRead=0;
export function availabilityKey(value){try{const u=new URL(value);if(u.protocol!=='https:'||u.username||u.password)return '';const host=u.hostname.toLowerCase();if(host==='linkedin.com'||host.endsWith('.linkedin.com')){const m=u.pathname.match(/\/jobs\/view\/(?:[^/?]*-)?(\d+)\/?$/);if(m)return 'linkedin:'+m[1];}if(host==='naukri.com'||host.endsWith('.naukri.com')){const m=u.pathname.match(/-(\d{10,})\/?$/);if(m)return 'naukri:'+m[1];}if(['indeed.com','in.indeed.com','www.indeed.com','indeed.co.in'].includes(host)&&u.searchParams.get('jk'))return 'indeed:'+u.searchParams.get('jk');for(const key of [...u.searchParams.keys()])if(/utm_|^(trk|ref|source)$/i.test(key))u.searchParams.delete(key);u.searchParams.sort();u.hash='';u.pathname=u.pathname.replace(/\/$/,'');return 'url:'+u.href.replace(/\/$/,'');}catch{return '';}}
export function closureQuote(text){return String(text||'').split(/\b(?:Similar jobs|People also viewed|Recommended jobs)\b/i)[0].replace(/\s+/g,' ').match(closedPattern)?.[0]||'';}
export function isUnavailable(job,keys=knownClosed){return job?.is_expired===true||job?.job_is_open===false||job?.accepting_applications===false||['closed','expired','filled','withdrawn','inactive'].includes(String(job?.availability_status||job?.job_status||'').toLowerCase())||!!closureQuote(String(job?.application_status||'')+'\n'+String(job?.description||''))||keys.has(availabilityKey(job?.url));}
export async function loadClosedJobs(refresh=false){if(!refresh&&Date.now()-lastRead<300000)return;if(pending)return pending;pending=(async()=>{const urls=['https://raw.githubusercontent.com/H-ana/NextRole/main/nextrole/dist/closed-jobs.json',new URL('./closed-jobs.json',import.meta.url).href];const reads=await Promise.allSettled(urls.map(async url=>{const r=await fetch(url,{cache:refresh?'reload':'default',signal:AbortSignal.timeout(8000)});if(!r.ok)throw Error('Unavailable');const text=await r.text();if(text.length>2000000)throw Error('Too large');const d=JSON.parse(text);if(d.format!=='nextrole-closed-jobs'||d.version!==1||!Number.isFinite(d.updated_at)||!Array.isArray(d.entries))throw Error('Invalid status data');return d;}));const valid=reads.filter(r=>r.status==='fulfilled').map(r=>r.value).sort((a,b)=>b.updated_at-a.updated_at);if(valid.length){knownClosed=new Set(valid[0].entries.filter(r=>r?.status==='closed'&&typeof r.key==='string'&&r.key.length<2000).map(r=>r.key));lastRead=Date.now();}})().finally(()=>pending=null);return pending;}

export function rememberClosedJobs(entries){for(const row of Array.isArray(entries)?entries:[])if(row?.status==='closed'&&typeof row.key==='string'&&row.key.length<2000)knownClosed.add(row.key);}
